def label_for(table: Mapping[str, Any], key: str) -> str:
    """The Persian label for key; the raw key when the table has no entry."""
    entry = table.get(key)
    if entry is None:
        return key
    if isinstance(entry, Mapping):
        return str(entry["label"])
    return str(entry)
